import fs from 'fs';
import path from 'path';
import {
  AUTH_REQUIRED_MESSAGE,
  errorResult,
  okResult,
  type CliCommandResult,
} from '../envelope';
import { isCommandResult, parseCommandContext } from './shared';
import type {
  NormalizedPin,
  PinterestFetchFailureReason,
} from '../../services/IntegrationsClient';
import { errorMessage } from '../../utils/errorMessage';

const COMMAND = 'reference.fetch';

const MAX_IMAGE_DOWNLOADS = 12;
const IMAGE_DOWNLOAD_TIMEOUT_MS = 15_000;

const FAILURE_GUIDANCE: Record<PinterestFetchFailureReason, string> = {
  pin_not_accessible:
    'Pinterest only lets Rivet read pins saved to the connected account, and this pin has no readable public data. Ask the user to save the pin to any of their Pinterest boards, then retry this command.',
  unsupported_url:
    'This link does not resolve to a Pinterest pin or board URL.',
  board_not_owned:
    'This board belongs to a different Pinterest account than the one connected to Rivet. Boards can only be read from the connected account.',
  board_owner_unverified:
    'The connected Pinterest account has no stored username, so Rivet cannot verify this board belongs to it. Ask the user to reconnect Pinterest from the Rivet editor, then retry.',
  board_not_found:
    'No board with this name was found on the connected Pinterest account.',
  rate_limited:
    'Pinterest temporarily limited requests. Wait for the retry interval, then retry this command.',
};

const downloadPinImages = async (
  projectPath: string,
  pins: NormalizedPin[],
): Promise<string[]> => {
  const dir = path.join(projectPath, '.rivet', 'references');
  const localPaths: string[] = [];
  let dirReady = false;

  for (const pin of pins.slice(0, MAX_IMAGE_DOWNLOADS)) {
    const imageUrl = pin.image_urls[pin.image_urls.length - 1];
    if (!imageUrl || !pin.id) {
      continue;
    }
    try {
      const response = await fetch(imageUrl, {
        signal: AbortSignal.timeout(IMAGE_DOWNLOAD_TIMEOUT_MS),
      });
      if (!response.ok) {
        continue;
      }
      if (!dirReady) {
        fs.mkdirSync(dir, { recursive: true });
        dirReady = true;
      }
      const ext =
        path.extname(new URL(imageUrl).pathname).toLowerCase() || '.jpg';
      const filePath = path.join(
        dir,
        `pinterest-${pin.id.replace(/[^a-zA-Z0-9_-]/g, '')}${ext}`,
      );
      fs.writeFileSync(filePath, Buffer.from(await response.arrayBuffer()));
      pin.local_path = filePath;
      localPaths.push(filePath);
    } catch {
    }
  }
  return localPaths;
};

type ReferenceProvider = 'pinterest' | 'arena';

const detectProvider = (url: string): ReferenceProvider | null => {
  let host: string;
  try {
    host = new URL(url).hostname.toLowerCase();
  } catch {
    return null;
  }
  if (
    host === 'pin.it' ||
    host === 'pinterest.com' ||
    host.endsWith('.pinterest.com')
  ) {
    return 'pinterest';
  }
  if (host === 'are.na' || host.endsWith('.are.na')) {
    return 'arena';
  }
  return null;
};

export const handleReferenceFetch = async (
  args: string[],
): Promise<CliCommandResult> => {
  const context = parseCommandContext(COMMAND, args);
  if (isCommandResult(context)) {
    return context;
  }
  const url = context.flags.positionals[0];
  if (!url) {
    return errorResult(
      COMMAND,
      'USAGE_ERROR',
      'Usage: rivet reference fetch <url>',
    );
  }

  const provider = detectProvider(url);
  if (!provider) {
    return okResult(COMMAND, {
      status: 'unsupported',
      message:
        'Unsupported design-reference URL. rivet reference fetch handles Pinterest (pinterest.com / pin.it) and Are.na (are.na) links.',
    });
  }

  const { getConfigManager } = await import('../../services/ConfigManager');
  if (!getConfigManager().isAuthenticated()) {
    return errorResult(
      COMMAND,
      'AUTH_REQUIRED',
      AUTH_REQUIRED_MESSAGE,
      { provider },
    );
  }

  const { IntegrationsClient } =
    await import('../../services/IntegrationsClient');
  const client = new IntegrationsClient();
  try {
    if (provider === 'pinterest') {
      const result = await client.fetchPinterest(url);

      if (result.status === 'error') {
        return errorResult(
          COMMAND,
          'OPERATION_FAILED',
          result.reason ? FAILURE_GUIDANCE[result.reason] : result.message,
          {
            reason: result.reason,
            retryAfterMs: result.retryAfterMs,
            provider,
            providerMessage: result.message,
          },
        );
      }

      if (result.status === 'ok') {
        const images = await downloadPinImages(
          context.projectPath,
          result.pins,
        );
        return okResult(COMMAND, { provider, ...result, images });
      }

      const connectResult = await client.connect('pinterest');
      if (connectResult.status === 'error') {
        return errorResult(
          COMMAND,
          'OPERATION_FAILED',
          `Pinterest is not connected, and Rivet could not start authorization: ${connectResult.message}`,
          {
            provider,
            providerMessage: connectResult.message,
          },
        );
      }
      return okResult(COMMAND, {
        provider,
        status: 'not_connected',
        authUrl: connectResult.authUrl,
        message:
          'Pinterest is not connected. Ask the user to authorize Pinterest with this link, then retry the design-context request.',
      });
    }

    const result = await client.fetchArena(url);
    if (result.status === 'error') {
      return errorResult(COMMAND, 'OPERATION_FAILED', result.message, {
        provider,
        reason: result.reason,
        retryAfterMs: result.retryAfterMs,
      });
    }
    return okResult(COMMAND, { provider, ...result });
  } catch (error) {
    return errorResult(
      COMMAND,
      'OPERATION_FAILED',
      errorMessage(error, 'Reference fetch failed'),
      { provider },
    );
  }
};
